const raw = $input.first().json.body || $input.first().json;
const pick = (...keys) => { for (const k of keys) { if (raw[k]) return String(raw[k]).trim(); } return ''; };
const email = pick('email','Email','work_email').toLowerCase();
const fullName = pick('name','full_name','Name');
const nameParts = fullName.split(/\s+/);
return [{ json: {
  email,
  firstName: nameParts[0] || '',
  lastName: nameParts.slice(1).join(' ') || '',
  fullName,
  phone: pick('phone','Phone').replace(/(?!^\+)[^\d]/g, ''),
  company: pick('company','Company'),
  message: pick('message','Message'),
  emailOk: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
} }];
